import{_ as o,l as i,o as e,c as n,v as t,p as s,x as l,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"生成元与离散对数","description":"","frontmatter":{"title":"生成元与离散对数","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/generator-discrete-log.md","filePath":"cs/generator-discrete-log.md","lastUpdated":1789023840000}'),g={name:"cs/generator-discrete-log.md"};function c(m,a,D,_,f,b){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="生成元与离散对数" tabindex="-1">生成元与离散对数 <a class="header-anchor" href="#生成元与离散对数" aria-label="Permalink to &quot;生成元与离散对数&quot;">​</a></h1><div class="epigraph"><p>循环群 $G=\\langle g\\rangle$ 里，已知 $g,g^a$ 求 $a$ 叫离散对数。正向模幂易，反向在谨慎选择的群里难——DH 停在这一不对称上。</p><footer>—— 据 Diffie and Hellman, 1976；Ireland and Rosen 整理</footer></div><p>上一课<a href="/cs/finite-field-gf2n">GF(2ⁿ)</a> 给出有限域。缺口是乘群的<strong>循环生成元</strong>与 DLP。主干<a href="/cs/diffie-hellman-paper">DH</a> 已用 \\(g^a,g^b\\)；本课钉：何谓生成元、阶、安全子群，不重做密钥交换报文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有限域乘群循环：存在 \\(g\\)，\\(\\mathrm{ord}(g)=q-1\\)。\\(g\\) 生成元（原根）。\\(\\log_g h\\) 是 \\(g^x=h\\) 的 \\(x\\)。Baby-step giant-step \\(O(\\sqrt{|G|})\\)，Pohlig–Hellman 把阶分解成小素因子——故 \\(|G|\\) 要有大素因子。素数域 \\(\\mathbb{F}_p\\) 选安全素数 \\(p=2q+1\\)，或用大素子群。椭圆曲线上同样定义 DLP，群运算不同，后课。</p><p>OWF 课：模幂（固定 \\(g\\)）是候选单向；陷门不在 DH，在 RSA。</p><h3 id="不是「对数表」" tabindex="-1">不是「对数表」 <a class="header-anchor" href="#不是「对数表」" aria-label="Permalink to &quot;不是「对数表」&quot;">​</a></h3><p>实数 \\(\\log\\) 连续可算。DLP 在离散循环群，没有单调可用的牛顿法。指标演算对 \\(\\mathbb{F}_p\\) 亚指数，对椭圆曲线一般不适用——这是 ECC 参数更短的原因，后课点到即可。</p><p><span class="marginnote">Diffie–Hellman 1976。Shoup 的下界在泛型群。Ireland–Rosen 原根存在性（模 \\(p\\)）。本课不证存在性全部情形。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 \\(\\mathbb{F}_7^\\times\\) 找生成元，列幂表当「玩具 DLP」。说明 Pohlig–Hellman：阶光滑则易。对照扩展欧几里得：那是加群 \\(\\mathbb{Z}/n\\mathbb{Z}\\) 上的「对数」（乘法逆），多项式；乘群上不是。</p>',11)),(e(),s(h,null,{default:l(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%BE%AA%E7%8E%AF%E7%BE%A4%20%E2%9F%A8g%E2%9F%A9%22%5D%20--%3E%20POW%5B%22x%20%E2%86%A6%20g%5Ex%20%E6%98%93%22%5D%0A%20%20POW%20--%3E%20DLP%5B%22h%20%E2%86%A6%20log_g%20h%20%E9%9A%BE%22%5D%0A%20%20DLP%20--%3E%20PH%5B%22%E9%98%B6%E5%85%89%E6%BB%91%E5%88%99%20Pohlig%E2%80%93Hellman%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DH 的机密是 \\(g^{ab}\\)，被动者看见 \\(g^a,g^b\\)。CDH、DDH 是更细的假设。本课只要 DLP 陈述。生成元检验：对 \\(|G|\\) 的每个素因子 \\(q\\)，\\(g^{|G|/q}\\ne 1\\)。</p><p>RSA 的「对数」是对 \\(e\\) 求 \\(d\\)，秘密是 \\(\\varphi(n)\\)，不是同一问题。</p><p>检验生成元：对 \\(|G|\\) 的每个素因子 \\(q\\) 测 \\(g^{|G|/q}\\neq 1\\)。安全素数 \\(p=2q+1\\) 使阶只有因子 \\(2,q\\)。DDH：\\((g^a,g^b,g^{ab})\\) 与 \\((g^a,g^b,g^c)\\) 不可分，比 CDH 更强，许多协议真正用 DDH。本课 DLP 足够解释「正向易反向难」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写指标演算，不选具体 RFC 素数。不引入双线性对。后课默认：循环群上正向幂易、DLP 要硬，则阶不可光滑。下一课二次剩余。</p><p>循环群上幂易、对数难，是 DH 的全部不对称。阶光滑则 Pohlig–Hellman 拆开它。RSA 的「求 \\(d\\)」靠 \\(\\varphi(n)\\) 秘密，不是同一问题。ECC 后课换群、同形 DLP。</p><p>上一课留下的缺口在本课收口；「生成元与离散对数」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>有限域乘群循环；生成元的幂覆盖全体非零。</li><li>DLP：已知 \\(g^a\\) 求 \\(a\\)；光滑阶则易。</li><li>DH 建立在此不对称上，本课不重做协议。</li><li>出处：Diffie and Hellman, 1976；Ireland and Rosen。</li></ul>',10))])}const u=o(g,[["render",c]]);export{E as __pageData,u as default};
